        public static IEnumerable<TestCaseData> Cases() => Fixtures
            .Where(f => Apis.IsPorted(f.type))
            .Select(f => new TestCaseData(f.type, f.json).SetName($"{TypeNames.Of(f.type).Replace("ApiLibs.", "")} ({f.name})"));

        [TestCaseSource(nameof(Cases))]
        public void Read(Type oldType, string json)
        {
            // Report whether the base document parses at all: a fixture both sides reject only proves they agree on failing.
            var (_, baseError) = Parsing.Try(() => Parsing.Old(json, oldType));
            TestContext.WriteLine(baseError == null ? "base parses" : $"base throws {baseError.GetType().Name}: {baseError.Message.Split('\n')[0]}");

            var failures = new List<string>();
            foreach (var (name, variant) in Mutations.Of(json))
            {
                var difference = Parsing.Compare(variant, oldType);
                if (difference != null)
                {
                    failures.Add($"[{name}] {difference}");
                }
            }
            // Write back what was read, the way requests send objects (Param / request bodies).
            if (baseError == null)
            {
                var oldValue = Parsing.Old(json, oldType);
                var newValue = Parsing.New(json, Apis.NewTypeFor(oldType)!);
                var (oldText, oldWriteError) = Parsing.Try(() => new ApiLibs.Param("p", oldValue).Value);
                var (newText, newWriteError) = Parsing.Try(() => new ApiLibs.JSON.Param("p", newValue).Value);
                if (oldWriteError != null || newWriteError != null)
                {
                    if (oldWriteError == null || newWriteError == null)
                    {
                        failures.Add($"write: {Parsing.Outcome(oldText, oldWriteError, newText, newWriteError)}");
                    }
                }
                else
                {
                    var difference = JsonTrees.Difference(JsonTrees.Parse((string)oldText!), JsonTrees.Parse((string)newText!), "$");
                    if (difference != null)
                    {
                        failures.Add($"write: {difference}");
                    }
                }
                TestContext.WriteLine(oldWriteError == null ? "base writes" : $"base write throws {oldWriteError.GetType().Name}");
            }

            Assert.That(failures, Is.Empty, string.Join("\n", failures.Take(15)));
        }
    }
